$t['Keep a working Web Encoder configured. AVideo still uses it for live previews, video and timeline thumbnails, recordings, playlist-to-live processing and other server-side media services.'] = '작동하는 Web Encoder를 계속 구성해 두세요. AVideo는 라이브 미리보기, 동영상 및 타임라인 썸네일, 녹화, 재생목록 라이브 처리 및 기타 서버 측 미디어 서비스에 여전히 이를 사용합니다.';
$t['Keep Key Private, Anyone with key can broadcast on your account'] = 'Key Private(키 비공개) 유지, 키가 있는 사람은 누구나 계정에서 브로드캐스트할 수 있음';
