$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = '커밋은 이 서버에 체크아웃된 Git 리비전을 나타내며, 로컬 파일 수정 사항은 포함되지 않습니다. 해당 커밋을 직접 가리키는 Git 태그가 있으면 함께 표시됩니다.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = '현재 Companion Chat 서비스를 사용할 수 없습니다. 사이트 관리자에게 AI 플러그인 연결을 확인해 달라고 요청하세요.';
$t['The connection could not be renewed. Please reconnect your account.'] = '연결을 갱신할 수 없습니다. 계정을 다시 연결해 주세요.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = '연결이 만료되어 갱신할 수 없습니다. 계정을 다시 연결해 주세요.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = '스트리밍 중에 대상과의 연결이 끊어졌습니다. 일시적인 네트워크 문제일 수 있으며, FFMPEG가 다시 연결을 시도합니다.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'YouTube 연결이 중단되었습니다. 업로드가 일시 중지되었으며 다시 시작할 수 있습니다.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = '연결이 중단되었습니다. 이 구독을 다시 시도하기 전에 계정을 확인하세요.';
$t['The connection was renewed.'] = '연결이 갱신되었습니다.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = '인증이 완료되기 전에 연결 창이 닫혔습니다. 연결된 계정이 없습니다.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = '변환된 파일은 보관되었습니다. 전송을 다시 시도하려면 사이트 관리자에게 문의하세요. 동영상을 다시 업로드할 필요는 없습니다.';
$t['The converted video could not be sent back to this site.'] = '변환된 동영상을 이 사이트로 다시 보낼 수 없습니다.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = '선택한 카드의 고객입니다. 검색, 정렬, 이메일 복사 또는 전체를 스프레드시트로 내보낼 수 있습니다.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = '이 웹사이트의 일일 YouTube 업로드 할당량에 도달했습니다. 태평양 시간 자정 이후에 다시 업로드할 수 있습니다. 나중에 다시 시도하세요.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = '데이터베이스 버전은 데이터베이스 마이그레이션이 적용될 때만 변경됩니다. 릴리스 태그나 커밋과 일치하지 않아도 됩니다.';
$t['The default'] = '기본값';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = '대상 RTMP 서버가 연결을 거부했습니다. 스트림 URL을 확인하고 서버가 온라인 상태인지 확인하세요.';
$t['The destination server requires authentication. Check the stream key.'] = '대상 서버에 인증이 필요합니다. 스트림 키를 확인하세요.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = '대상 서버가 403을 반환했습니다. 스트림 키가 잘못되었거나 만료되었을 수 있습니다.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = '대상 동영상이 삭제되었거나 이 계정으로 편집할 수 없습니다. 사이트에서 동영상과 계정 접근 권한을 확인하세요.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'The download is controlled by the system, there is nothing to check on the user';
$t['The download permission is site wide, so there is nothing to check on the video'] = '다운로드 권한은 사이트 전체에 적용되므로 동영상에서 확인할 항목이 없습니다';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'The download permission is site wide, so there is nothing to check onthe video';
$t['The email is invalid'] = '이메일이 잘못됨';
$t['The encoder could not download the original file.'] = '인코더가 원본 파일을 다운로드할 수 없습니다.';
$t['The encoder could not find this video on the site.'] = '인코더가 사이트에서 이 동영상을 찾을 수 없습니다.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = '인코더가 동영상이 대기열에 추가되었음을 확인하지 않았습니다. 다시 시도하세요.';
$t['The encoder is running out of disk space'] = '인코더의 디스크 공간이 부족합니다';
$t['The encoder reported an unexpected error.'] = '인코더에서 예기치 않은 오류가 발생했습니다.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = '인코딩 프로세스가 예기치 않게 중지되었으며 자동 재시도도 실패했습니다.';
$t['The encoding queue is stalled'] = '인코딩 대기열이 멈췄습니다';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = '이벤트 구매를 완료할 수 없습니다. 지갑 결제 금액은 차감되지 않았습니다. 다시 시도하기 전에 잔액을 확인하세요.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = '파일을 변환할 수 없습니다. 파일이 손상되었거나 인코더가 지원하지 않는 형식일 수 있습니다.';
$t['The file must be an .vtt file!'] = 'The file must be an .vtt file!';
$t['The file must be an .vtt or .srt file!'] = '파일은 .vtt 또는 .srt 파일이어야 합니다!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = '최종 요금은 처리 중에 측정된 길이를 기준으로 합니다. 연결된 Marketplace 지갑이 필요합니다.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = '다음 영화에는 17세 이하 어린이에게 적합하지 않은 내용이 포함되어 있습니다.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = '다음 영화에는 17세 이하 어린이에게 적합하지 않을 수 있는 내용이 포함되어 있습니다.';
$t['The form to signup will not exists'] = 'The form to signup will not exists';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = '기프트 코드가 취소되었습니다. 예상하지 못한 경우 지원팀에 문의하세요.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = '기프트 코드가 현재 비활성 상태입니다. 나중에 다시 확인하거나 지원팀에 문의하세요.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = '위 정보는 당사의 공식 기록과 일치하며 이 인증서의 진위를 확인합니다.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = '입력 스트림에 잘못된 데이터가 포함되어 있습니다. 소스 HLS가 아직 준비되지 않았거나 스트림이 중단되었을 수 있습니다.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = '설치된 PHP 패키지에는 두 수정 사항이 모두 포함되어 있지만, 이 웹 프로세스는 아직 업데이트 이전에 로드된 버전을 실행 중입니다. Apache 또는 PHP-FPM을 재시작하세요.';
$t['Their last plans add up to %s'] = '마지막 플랜의 합계는 %s입니다';
$t['The list was limited to the first %s results.'] = '목록은 처음 %s개의 결과로 제한되었습니다.';
$t['The live service could not complete the request. Please try again.'] = '라이브 서비스가 요청을 완료할 수 없습니다. 다시 시도하세요.';
$t['The live that was still being sent to this destination was stopped.'] = '이 대상으로 아직 전송 중이던 라이브가 중지되었습니다.';
$t['Theme for Style:'] = 'Theme for Style:';
$t['Themes'] = '테마';
$t['The number of lines in both columns must be the same'] = '두 열의 줄 수가 같아야 합니다';
$t['The original file for this video does not exists anymore'] = 'The original file for this video does not exists anymore';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'The Permissions Plugin is not installed. Please install it if you want to customize the permissions.';
$t['The plugin is disabled'] = 'The plugin is disabled';
$t['The program is empty'] = 'The program is empty';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = '구매를 완료할 수 없습니다. 지갑 결제 금액은 차감되지 않았습니다. 다시 시도하기 전에 잔액을 확인하세요.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = '이 기프트 코드의 상태를 알 수 없습니다. 지원팀에 문의하세요.';
$t['There, you can set'] = 'There, you can set';
$t['There are no notifications'] = '알림이 없습니다';
$t['There are no upcoming events for this channel'] = '이 채널에 예정된 이벤트가 없습니다';
$t['There are various kinds of media you can integrate here. They are working different'] = 'There are various kinds of media you can integrate here. They are working different';
$t['The recover pass does not match!'] = '복구 패스가 일치하지 않음!';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'The regular form to signin will not exist, if you check this will only have social login or LDAP option';
$t['There is missing data to recover your password'] = '암호를 복구할 데이터가 누락됨';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = '아직 Pay Per View 플랜이 없습니다. Pay-Per-View 플러그인의 PPV Plans 탭에서 만드세요.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = '아직 동영상을 담을 수 있는 플랜이 없습니다. PPV Plans 탭에서 만든 후 여기로 돌아오세요.';
$t['There is no streaming now'] = '지금 스트리밍이 없다.';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = '릴리스 번호와 AVideo 데이터베이스 버전은 서로 독립적입니다. 코드 업데이트 상태는 커밋 기록으로 판단됩니다.';
$t['The request to the social network failed. Please try again later.'] = '소셜 네트워크 요청에 실패했습니다. 나중에 다시 시도하세요.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = '리스트리머 서버가 대상에 연결할 수 없습니다. 네트워크 연결을 확인하세요.';
$t['The same alert is repeated at most every %s while the problem continues.'] = '문제가 계속되는 동안 같은 알림은 최대 %s마다 반복됩니다.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = '문제가 계속되는 동안 같은 알림은 최대 몇 시간마다 반복됩니다.';
$t['The selected camera or microphone is not available. Please choose another device.'] = '선택한 카메라 또는 마이크를 사용할 수 없습니다. 다른 장치를 선택하세요.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = '선택한 위치가 실제 페이지에 강조 표시됩니다. 모바일 미리보기는 광고 위치만 변경하며, 페이지의 나머지 부분은 브라우저 장치를 사용합니다.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = '선택한 위치는 사이트의 실제 페이지에 윤곽선으로 표시되며, 아래에서 선택하는 위치에 따라 바뀝니다. 모바일 미리보기는 광고 위치만 변경하며, 페이지의 나머지 부분은 사용 중인 브라우저 기기 기준으로 표시됩니다.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = '데이터베이스 문제로 현재 사이트가 오프라인 상태입니다. 최대한 빨리 문제를 해결하기 위해 노력하고 있습니다.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = '서버 디스크가 가득 차서 사이트를 일시적으로 사용할 수 없습니다. 문제를 해결 중이며 곧 돌아오겠습니다.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = '서버 디스크 용량이 거의 가득 차서 사이트 유지보수 중입니다. 문제를 해결 중이며 곧 돌아오겠습니다.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = '사이트가 접근을 거부했습니다. 인코더 계정 접근 권한을 갱신하고 업로드 권한을 확인하세요.';
$t['The site will display only a login form to un authenticated users'] = 'The site will display only a login form to un authenticated users';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = '소스 스트림이 종료되었습니다. 라이브를 의도적으로 중지한 경우 정상입니다.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = '분할이 켜져 있습니다. 데스크톱 방문자에게는 이제 이 배너가 표시되지 않고 왼쪽과 오른쪽 절반이 표시됩니다.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = '스트림에 타임스탬프 불연속이 있습니다. 이로 인해 대상 플랫폼에서 버퍼링이나 재생 문제가 발생할 수 있습니다.';
$t['The subtitle has not been copied to the player yet.'] = '자막이 아직 플레이어에 복사되지 않았습니다.';
$t['The subtitle is already on the player.'] = '자막이 이미 플레이어에 있습니다.';
$t['The subtitle was copied to the player.'] = '자막이 플레이어에 복사되었습니다.';
$t['The subtitle will be available when processing finishes.'] = '처리가 완료되면 자막을 사용할 수 있습니다.';
$t['The upload could not be started. Please try again.'] = '업로드를 시작할 수 없습니다. 다시 시도하세요.';
$t['The upload did not start. Click Resume to try again.'] = '업로드가 시작되지 않았습니다. 다시 시도하려면 재개를 클릭하세요.';
$t['The upload to YouTube started. You can follow its progress below, it continues even if you close this window.'] = 'YouTube 업로드가 시작되었습니다. 아래에서 진행 상황을 확인할 수 있으며, 이 창을 닫아도 계속 진행됩니다.';
$t['The upload was canceled.'] = '업로드가 취소되었습니다.';
$t['The upload was interrupted. Click Resume to continue from where it stopped.'] = '업로드가 중단되었습니다. 중단된 지점부터 계속하려면 재개를 클릭하세요.';
$t['The upload was resumed.'] = '업로드가 재개되었습니다.';
$t['the user is inactive'] = 'the user is inactive';
$t['The username must be an email'] = 'The username must be an email';
$t['The user will be able to edit their name and CPF.'] = '사용자가 이름과 CPF를 편집할 수 있습니다.';
$t['The video could not be published. Please try again later.'] = '동영상을 게시할 수 없습니다. 나중에 다시 시도하세요.';
$t['The video file could not be found on this server, so it cannot be sent to YouTube.'] = '이 서버에서 동영상 파일을 찾을 수 없어 YouTube로 보낼 수 없습니다.';
$t['The video is empty'] = 'The video is empty';
$t['The video was published.'] = '동영상이 게시되었습니다.';
$t['The website pages do not display this position, so there is nothing to preview.'] = '웹사이트 페이지에 이 위치가 표시되지 않으므로 미리볼 내용이 없습니다.';
$t['The website pages do not display this position at the moment. Images saved here are only returned by the API.'] = '현재 웹사이트 페이지에는 이 위치가 표시되지 않습니다. 여기에 저장된 이미지는 API로만 반환됩니다.';
$t['They are likely to leave at renewal time. Invite them back with a suggested course or a live class.'] = '갱신 시점에 이탈할 가능성이 높습니다. 추천 강좌나 라이브 수업으로 다시 초대하세요.';
$t['They have paid %s in total'] = '총 %s을(를) 결제했습니다';
$t['The YouTube authorization could not be renewed because the authorization service did not answer. Please try again in a few minutes.'] = '인증 서비스가 응답하지 않아 YouTube 인증을 갱신할 수 없습니다. 몇 분 후에 다시 시도하세요.';
$t['The YouTube categories could not be loaded, YouTube will choose one.'] = 'YouTube 카테고리를 불러올 수 없어 YouTube가 카테고리를 선택합니다.';
$t['The YouTube integration is not configured correctly. Please contact the site administrator.'] = 'YouTube 연동이 올바르게 구성되지 않았습니다. 사이트 관리자에게 문의하세요.';
