$t['YouTube: Google only lists channels you own or manage as a Brand Account. If your channel is not listed, fill in its stream URL and stream key by hand in the form.'] = 'YouTube: Google은 직접 소유하거나 브랜드 계정으로 관리하는 채널만 표시합니다. 채널이 목록에 없으면 양식에 스트림 URL과 스트림 키를 직접 입력하세요.';
