$t['YouTube did not accept the video details. Check the title, description and tags, then publish again.'] = 'YouTube에서 동영상 세부 정보를 허용하지 않았습니다. 제목, 설명, 태그를 확인한 후 다시 게시하세요.';
$t['YouTube did not allow this upload. Reconnect your YouTube account and allow this website to manage your YouTube videos.'] = 'YouTube에서 이 업로드를 허용하지 않았습니다. YouTube 계정을 다시 연결하고 이 웹사이트가 YouTube 동영상을 관리하도록 허용하세요.';
$t['YouTube is receiving too many requests right now. Please wait a few minutes and try again.'] = '현재 YouTube에 요청이 너무 많습니다. 몇 분 후에 다시 시도하세요.';
$t['YouTube rejected the video because it does not follow the YouTube policies.'] = 'YouTube 정책을 준수하지 않아 YouTube에서 동영상을 거부했습니다.';
